const vb = (kind, m, f) => CH_FEM[kind] ? f : m;
const stName = (st, kind) => st ? (CH_FEM[kind] ? st.f : st.name) : '';
const TORSO_RE = /^(<ellipse class="c-main" cx="50" cy="84" rx="22" ry="12\.5"\/>(?:<ellipse class="c-light" cx="50" cy="86\.5" rx="11\.5" ry="7\.5"\/>)?(?:<path d="M41 80[^>]*\/>)?)/;
const PARTS = {};
function partsOf(kind) {
  if (PARTS[kind]) return PARTS[kind];
  const c = CHARS[kind] || CHARS.cat, m = c.body.match(TORSO_RE);
  return (PARTS[kind] = m ? { torso:m[1], head:c.body.slice(m[1].length) } : { torso:'', head:c.body });
}

